import{_ as a,o as e,c as r,ag as d}from"./chunks/framework.DMXcdKmJ.js";const c=JSON.parse('{"title":"核对 AI 创建的数据配置","description":"找到 AI 创建的 SQL 查询、数据点、计算和报警，逐项核对保存、生成、调试与正式运行结果。","frontmatter":{"title":"核对 AI 创建的数据配置","description":"找到 AI 创建的 SQL 查询、数据点、计算和报警，逐项核对保存、生成、调试与正式运行结果。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/ai-data-review.md","filePath":"zh/使用指南/核对AI创建的数据配置.md"}'),i={name:"zh/guide/ai-data-review.md"};function o(l,t,n,h,s,p){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="核对-ai-创建的数据配置" tabindex="-1">核对 AI 创建的数据配置 <a class="header-anchor" href="#核对-ai-创建的数据配置" aria-label="Permalink to &quot;核对 AI 创建的数据配置&quot;">​</a></h1><p>AI 说“写好了”，可能指写了一段说明、改了源码文件，也可能是已经保存了平台配置。<strong>先分清交付对象，再到真实界面核对，不只看聊天回复。</strong></p><p>开始前，确认仍在同一个组织和工程，并有该工程的查看或维护权限。</p><h2 id="_1-先让-ai-交付可查的信息" tabindex="-1">1. 先让 AI 交付可查的信息 <a class="header-anchor" href="#_1-先让-ai-交付可查的信息" aria-label="Permalink to &quot;1. 先让 AI 交付可查的信息&quot;">​</a></h2><p>可以这样要求：</p><blockquote><p>请说明本次是只修改源码，还是通过平台建模保存了配置。<br> 已保存的请逐项列出：所属接入源、查询或单元名称、对象 ID、生成的数据点完整路径、报警名称。<br> 分别说明哪些只是保存、哪些已执行或调试、哪些尚未验证。<br> 保存成功但上下文同步失败时，先重新读取确认，不重复创建。<br> 不要把临时样例、默认值或静态页面数据说成真实运行数据。</p></blockquote><p>对象 ID 用于核对同名项，不必由新手手工拼接接口地址。交付信息不全时，先请 AI 补齐实际读取结果，不让它猜一个路径。</p><h2 id="_2-不同成果去哪里看" tabindex="-1">2. 不同成果去哪里看 <a class="header-anchor" href="#_2-不同成果去哪里看" aria-label="Permalink to &quot;2. 不同成果去哪里看&quot;">​</a></h2><table tabindex="0"><thead><tr><th>AI 完成的内容</th><th>在平台哪里查看</th><th>核对重点</th></tr></thead><tbody><tr><td>SQL 查询</td><td>工程管理 → 目标工程 → 数据中心 → 接入源 → 对应数据库连接 → 保存查询</td><td>查询名称、SQL、参数、输出配置及是否生成点</td></tr><tr><td>SQL 等来源生成的数据点</td><td>数据中心 → 数据点</td><td>完整路径、来源、类型、当前值、质量和时间</td></tr><tr><td>计算单元</td><td>数据中心 → 计算单元 → 搜索并打开对应单元</td><td>输入点、脚本、触发方式、输出及启用状态</td></tr><tr><td>报警配置</td><td>数据中心 → 报警单元 → 查找对应报警</td><td>关联点、条件、级别、启用及恢复设置</td></tr><tr><td>页面组件或源码文件</td><td>应用开发 → 编辑器；随后打开“页面”</td><td>文件差异、真实取数、工程用户权限</td></tr><tr><td>正式运行变化</td><td>运维管理 → 工程部署与运维记录</td><td>实际模式、版本、环境、任务与健康状态</td></tr></tbody></table><p>计算、报警并不都显示成一个同名数据点。计算输出可生成点；报警要回报警单元查看配置，不能只在数据点列表搜索报警名称。</p><h2 id="_3-用-ai-参与过-找到点-再返回来源" tabindex="-1">3. 用“AI 参与过”找到点，再返回来源 <a class="header-anchor" href="#_3-用-ai-参与过-找到点-再返回来源" aria-label="Permalink to &quot;3. 用“AI 参与过”找到点，再返回来源&quot;">​</a></h2><ol><li>进入 <strong>“数据中心” → “数据点”</strong>。</li><li>在 **“配置编写来源”**选择 <strong>“AI 参与过”</strong>。</li><li>配合名称、路径或来源筛选找到本次对象。</li><li>点击“查看详情”，核对来源与“开发态当前值”。</li><li>使用来源入口返回对应接入源或计算单元，检查实际配置。</li></ol><p>“AI 参与过”表示平台记录了 AI 参与创建或修改，不是 AI 独占创建、审核通过或测试合格的标记。手工照抄 AI 给的 SQL，不会仅因文字来自 AI 就自动出现标记。</p><p>这个筛选位于<strong>数据中心的数据点列表</strong>，不要在所有计算、报警或应用开发列表中寻找同名筛选。没有标记时，仍按 AI 返回的真实名称、路径和来源查找，不立即判断成果丢失。</p><h2 id="_4-ai-写了-sql-但列表里没有数据点" tabindex="-1">4. AI 写了 SQL，但列表里没有数据点 <a class="header-anchor" href="#_4-ai-写了-sql-但列表里没有数据点" aria-label="Permalink to &quot;4. AI 写了 SQL，但列表里没有数据点&quot;">​</a></h2><p>先到对应连接的<strong>保存查询</strong>查找，不要立刻新建同名项。</p><ul><li>只有 SQL 文本或一个源码文件：尚不能证明已经保存查询。</li><li>保存了查询：检查“输出配置”，查询保存不等于点已生成。</li><li>已执行 SQL：结果表不等于可供页面调用的数据点。</li><li>已生成点：复制输出路径，再到数据点列表核对；查看“数据预览”时辨认真实值与配置预览。</li></ul><p>详细步骤见<a href="/induframe-docs/zh/guide/sql-datapoints.html">用 SQL 查询生成数据点</a>。需要一个数值供计算或报警使用时，检查提取后的类型，不把完整结果集对象当作一个数字。</p><h2 id="_5-从开发验证走到运行验证" tabindex="-1">5. 从开发验证走到运行验证 <a class="header-anchor" href="#_5-从开发验证走到运行验证" aria-label="Permalink to &quot;5. 从开发验证走到运行验证&quot;">​</a></h2><p>先核对源配置与点位，再检查计算、报警和页面。开发态默认值、样例消息或调试成功，不代表正式部署正在持续处理真实数据。</p><p>正式使用时按工程发布、更新部署流程明确提交新内容；<strong>“重新部署”只是重下发当前制品，不会自动采用最新开发配置。</strong></p><p>保存已确认但同步失败时，先使用工作区 <strong>“同步工程上下文”</strong>，让 AI 重新读取实际对象，不重复创建。</p><h2 id="结果不明确时" tabindex="-1">结果不明确时 <a class="header-anchor" href="#结果不明确时" aria-label="Permalink to &quot;结果不明确时&quot;">​</a></h2><p>清除筛选、核对工程与连接、刷新已有对象，再查看具体错误和运维记录。停止 AI、删除对话或切换分支不会撤销已经保存的平台配置。</p><p>下一步：<a href="/induframe-docs/zh/guide/datapoints.html">数据点列表</a> · <a href="/induframe-docs/zh/guide/workspace-datapoints.html">应用开发调用权限</a> · <a href="/induframe-docs/zh/guide/deployments.html">工程部署</a>。</p>',25)])])}const u=a(i,[["render",o]]);export{c as __pageData,u as default};
